            intent.latest_client_epoch = WireCounter::parse("2").unwrap();
            intent.latest_activation_token = WireCounter::ZERO;
            assert!(record_activation_intent(
                &mut intent,
                WireCounter::parse("2").unwrap(),
                WireCounter::parse("1").unwrap(),
